            {
                "title": {
                    "_value": "Diabetes Medicines",
                    "type": "text"
                },
                "link": [
                    {
                        "href": "https://medlineplus.gov/diabetesmedicines.html?utm_source=mplusconnect&utm_medium=service",
                        "rel": "alternate"
